"""Release URL setup, preview, automatic prefetch and scoped selection."""
import json,os,subprocess,tempfile
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
with tempfile.TemporaryDirectory(prefix='cfs-release-setup-') as tmp:
 fixture=Path(tmp)/'data.json';seed=json.loads(subprocess.check_output(['node','-e','process.stdout.write(JSON.stringify(require("./scripts/fixture").seed()))'],cwd=ROOT));ids=list(seed['remote'])[:2];seed['remote'][ids[0]]['name']='Freshly fetched scoped epic';fixture.write_text(json.dumps(seed))
 server=subprocess.Popen(['node','server.js','--fixture'],cwd=ROOT,env={**os.environ,'PORT':'8395','CFS_FIXTURE_FILE':str(fixture)},stdout=subprocess.PIPE,text=True)
 try:
  assert 'Release Review:' in server.stdout.readline()
  with sync_playwright() as p:
   browser=p.chromium.launch();page=browser.new_page(viewport={'width':1440,'height':1000});errors=[];requests=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:requests.append(json.loads(r.post_data)) if r.method=='POST' and r.url.endswith('/api/handler') else None)
   page.goto('http://127.0.0.1:8395');expect(page.locator('#epic-count')).to_have_text('6');page.locator('#search').fill('stale filter from another release');page.locator('#new-release').click();expect(page.locator('.connected-list').first).to_be_visible();chip=page.locator('.connected-list').first;chip.click();expect(page.locator('#epic-links')).to_have_value(chip.get_attribute('data-url'));chip.click();expect(page.locator('#epic-links')).to_have_value('')
   page.locator('#release-name').fill('Scoped release');page.locator('#epic-links').fill('\n'.join('https://gus.lightning.force.com/lightning/r/ADM_Epic__c/'+id+'/view' for id in ids));page.locator('#preview-release').click();expect(page.locator('#release-preview')).to_contain_text('2 epics');before=len([k for k in seed['docs'] if k.startswith('release:')]);assert len([k for k in json.loads(fixture.read_text())['docs'] if k.startswith('release:')])==before
   requests.clear();page.locator('#save-release').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('#epic-count')).to_have_text('2');expect(page.locator('#fetch-button')).to_be_enabled(timeout=20000);expect(page.locator('#epic-table')).to_contain_text('Freshly fetched scoped epic');expect(page.locator('#search')).to_have_value('');assert any(r.get('action')=='fetch' and 'cursor' in r for r in requests)
   saved=json.loads(fixture.read_text());release=next(v for k,v in saved['docs'].items() if k.startswith('release:') and v['name']=='Scoped release');assert set(release['epicIds'])==set(ids);assert all(saved['docs']['epic:'+id].get('fetchedAt') for id in ids);assert saved['remote']==seed['remote']
   page.goto('http://127.0.0.1:8395/?release='+release['id']);expect(page.locator('#epic-count')).to_have_text('2');page.get_by_role('button',name='Releases',exact=True).click();panel=page.locator('#release-select-options');panel.get_by_role('button',name='Clear all',exact=True).click();other=next(v for k,v in seed['docs'].items() if k.startswith('release:'));panel.get_by_text(other['name'],exact=True).click();page.keyboard.press('Escape');expect(page.locator('#epic-count')).to_have_text('6');
   for i in range(3):
    result=page.request.post('http://127.0.0.1:8395/api/handler',data={'action':'save-release','name':'Extra release '+str(i),'year':2026,'links':ids[0]}).json();assert result['ok'],result
   page.reload();expect(page.locator('#release-select option')).to_have_count(5);expect(page.locator('#new-release')).to_be_enabled();page.locator('#new-release').click();page.locator('#release-name').fill('Sixth release from plus');page.locator('#epic-links').fill(ids[0]);page.locator('#save-release').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('#fetch-button')).to_be_enabled(timeout=20000);expect(page.locator('#release-select option')).to_have_count(6)
   page.locator('#manage-button').click();expect(page.locator('.release-manager-row')).to_have_count(6);expect(page.locator('#manager-add-release')).to_be_enabled();page.locator('#manager-add-release').click();page.locator('#release-name').fill('Seventh release from manager');page.locator('#epic-links').fill(ids[1]);page.locator('#save-release').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('#fetch-button')).to_be_enabled(timeout=20000);expect(page.locator('#release-select option')).to_have_count(7)
   other_page=browser.new_page();other_page.goto('http://127.0.0.1:8395');expect(other_page.locator('#release-select option')).to_have_count(7)
   page.reload();expect(page.locator('#release-select option')).to_have_count(7);page.get_by_role('button',name='Releases',exact=True).click();picker=page.locator('#release-select-options');picker.get_by_role('button',name='Select all',exact=True).click();assert page.locator('#release-select').evaluate('(e)=>e.selectedOptions.length')==5;expect(picker.locator('input[type=checkbox]:disabled')).to_have_count(2);picker.get_by_role('button',name='Clear all',exact=True).click();expect(picker.locator('input[type=checkbox]:disabled')).to_have_count(0);picker.get_by_role('searchbox').fill('Seventh release');picker.locator('input[type=checkbox]').check();page.keyboard.press('Escape');expect(page.locator('#epic-count')).to_have_text('1');expect(page.locator('#epic-table')).to_contain_text(seed['remote'][ids[1]]['name'])
   page.get_by_role('button',name='Releases',exact=True).click();expect(picker.get_by_role('searchbox')).to_have_value('');expect(picker.locator('.multi-option-row')).to_have_count(7);page.keyboard.press('Escape')
   assert not errors,errors;browser.close();print('Release setup checks passed: connected-list chips, read-only preview, automatic fetch, shared persistence and release-scoped display.')
 finally:server.terminate();server.wait(timeout=10)
